            splitStrings: true,
        }

        var data = fs.readFileSync(input, "utf-8");
        jsconfuser.obfuscate(data, {
            "target": "node",
            "calculator": true,
            "compact": true,
            "hexadecimalNumbers": true,
            "controlFlowFlattening": 0.1,
